function call(fn: string, args: unknown[]): unknown {
  const f = (issues as unknown as Record<string, (...a: unknown[]) => unknown>)[fn]!;
  // 옛 벡터 생성기가 undefined 인자를 JSON으로 쓰며 null이 됐다. 선택 인자(requirementId)만 해당한다
  const fixed = args.map((a, i) => (a === null && fn === 'isStatusComment' && i === 1 ? undefined : a));
  try {
    const out = f(...fixed);
    return out === undefined ? { __undefined: true } : out;
  } catch (error) {
    return { __throws: (error as Error).name };
  }
}

describe('requirement-issues 벡터: 옛 TS가 낸 값과 글자까지 같다', () => {
  it.each(VECTORS.map((v, i) => ({ ...v, title: `${i} ${v.fn}` })))('$title', ({ fn, args, out }) => {
    expect(JSON.stringify(call(fn, args))).toBe(JSON.stringify(out));
  });
});
